#!/usr/bin/env bash
# L-SI box 85 TWO COPIES PER LEVEL (docs/si/box85-twocopies.md) self-check: pins; instances regenerated byte-equal from cfg/ (two85.py);
# every output (ana85, dec85, flipu85, pool85, lb84, priv84) recomputed and diffed with out/; FLIP-U, LOWER-BLIND, POOL-ALT, PRIV-FLIP
# never exceeded.
set -euo pipefail
cd "$(dirname "$0")"
sha1sum -c --quiet --strict pins.sha1
cmp -s gen83.py ../box83/gen83.py
t=$(mktemp -d); mkdir -p "$t/inst" "$t/out"
for c in cfg/*.json; do i=$(basename "$c" .json); python3 -I -B two85.py "$c" "$t/inst/$i.json"; cmp -s "$t/inst/$i.json" inst/$i.json; cmp -s "$t/inst/$i.names.json" inst/$i.names.json; done
bash runout85.sh "$t/out"
for f in out/*.out; do diff -q "$f" "$t/out/$(basename "$f")"; done
! grep -E "exU [1-9]|exE [1-9]" out/flipu85.out
! grep -v "mispredictions 0 " out/lb84.out
grep -q "POOL-ALT violations 0" out/pool85.out; ! grep -v "POOL-ALT violations 0" out/pool85.out
! grep -E "maxex_priv [1-9]|maxex_nopriv [1-9]" out/priv84.out
rm -rf "$t"
echo "box 85 checks: PASS"
